// Normalise three feed shapes into one, drop anything older than a week.
const WINDOW_DAYS = 7;
const cutoff = Date.now() - WINDOW_DAYS * 24 * 60 * 60 * 1000;

return $input.all().flatMap((item) => {
  const d = item.json;
  const link = d.link || d.guid || '';
  if (!link) return [];

  const published = new Date(d.isoDate || d.pubDate || Date.now());
  if (published.getTime() < cutoff) return [];

  // Feeds return HTML fragments of wildly different lengths; the model only
  // needs enough to judge the story, and trimming here keeps token cost flat.
  const snippet = String(d.contentSnippet || d.content || d.description || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 1200);

  let source = 'unknown';
  try { source = new URL(link).hostname.replace(/^www\./, ''); } catch (e) {}

  return [{
    json: {
      title: String(d.title || '').trim(),
      link,
      source,
      isoDate: published.toISOString(),
      contentSnippet: snippet,
    },
  }];
});

parameters.text:
=You are the editor deciding whether a property news item is worth an Instagram post for Rumah123.

Reject an item when it is: a corporate announcement with no reader benefit, a thinly rewritten press release, purely political, older than roughly a week, or so thin that a caption would have to invent the substance.

Accept when a real person searching for a home would be better off knowing this.

ARTICLE
Title: {{ $json.title }}
Published: {{ $json.isoDate }}
Source: {{ $json.source }}
Summary: {{ $json.contentSnippet }}

Decide, and if you accept it, name the angle and the audience it serves.

